34	import org.springframework.security.access.AccessDeniedException;
35	import org.springframework.validation.BindingResult;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles {@link DuplicateTelephoneException}, thrown when creating an owner whose normalized
128	     * telephone is already used by another owner, returning a 409 Conflict status.
129	     *
130	     * @param e The {@link DuplicateTelephoneException} to be handled
131	     * @param request {@link HttpServletRequest} object referring to the current request.
132	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
133	     */
134	    @ExceptionHandler(InvalidTelephoneException.class)
135	    @ResponseBody
136	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
137	        HttpStatus status = HttpStatus.BAD_REQUEST;
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
139	        return ResponseEntity.status(status).body(detail);
140	    }
141	
142	    @ExceptionHandler(DuplicateTelephoneException.class)
143	    @ResponseBody
144	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
145	        HttpStatus status = HttpStatus.CONFLICT;
146	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
147	        return ResponseEntity.status(status).body(detail);
148	    }
149	
150	    @ExceptionHandler(DuplicateEmailException.class)
151	    @ResponseBody
152	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
153	        HttpStatus status = HttpStatus.CONFLICT;
154	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
155	        return ResponseEntity.status(status).body(detail);
156	    }
157	
158	    @ExceptionHandler(DuplicateHouseholdException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
161	        HttpStatus status = HttpStatus.CONFLICT;
162	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
163	        return ResponseEntity.status(status).body(detail);
164	    }
165	
166	    @ExceptionHandler(DailyOwnerLimitException.class)
167	    @ResponseBody
168	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
169	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
170	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
171	        return ResponseEntity.status(status).body(detail);
172	    }
173	
174	    @ExceptionHandler(CityAtCapacityException.class)
175	    @ResponseBody
176	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
177	        HttpStatus status = HttpStatus.CONFLICT;
178	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
179	        return ResponseEntity.status(status).body(detail);
180	    }
181	
182	    /**
183	     * Handles exception thrown by Bean Validation on controller methods parameters
184	     *
185	     * @param e The {@link MethodArgumentNotValidException} to be handled
186	     * @param request {@link HttpServletRequest} object referring to the current request.
187	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
188	     */
189	    @ExceptionHandler(MethodArgumentNotValidException.class)
190	    @ResponseBody
191	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
192	        HttpStatus status = HttpStatus.BAD_REQUEST;
193	        BindingErrorsResponse errors = new BindingErrorsResponse();
194	        BindingResult bindingResult = e.getBindingResult();
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        if (bindingResult.hasErrors()) {
197	            errors.addAllErrors(bindingResult);
198	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
199	                .map(fieldError -> {
200	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
201	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
202	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
203	                        fieldError.getField(),
204	                        defaultMessage,
205	                        rejectedValue);
206	                    return new ValidationMessageDto(message)
207	                        .putAdditionalProperty("field", fieldError.getField())
208	                        .putAdditionalProperty("rejectedValue", rejectedValue)
209	                        .putAdditionalProperty("defaultMessage", defaultMessage);
210	                })
211	                .toList();
212	            logger.debug("Validation error at {} {}: {}",
213	                request.getMethod(),
214	                request.getRequestURI(),
215	                bindingResult.getFieldErrors());
216	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
217	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
218	                .map(fieldError -> fieldError.getField())
219	                .distinct()
220	                .toList());
221	            return ResponseEntity.status(status).body(detail);
222	        }
223	        return ResponseEntity.status(status).body(detail);
224	    }
225	
226	}
